use crate::foundations::{Cast, Content, Smart, elem, scope};
use crate::layout::{Alignment, Em, Length, Rel};

/// Places content relatively to its parent container.
///
/// Placed content can be either overlaid (the default) or floating. Overlaid
/// content is aligned with the parent container according to the given
/// @place.alignment[`alignment`], and shown over any other content added so far
/// in the container. Floating content is placed at the top or bottom of the
/// container, displacing other content down or up respectively. In both cases,
/// the content position can be adjusted with @place.dx[`dx`] and
/// @place.dy[`dy`] offsets without affecting the layout.
///
/// The parent can be any container such as a @block, @box, @rect, etc. A top
/// level `place` call will place content directly in the text area of the
/// current page. This can be used for absolute positioning on the page: with a
/// `top + left` @place.alignment[`alignment`], the offsets `dx` and `dy` will
/// set the position of the element's top left corner relatively to the top left
/// corner of the text area. For absolute positioning on the full page including
/// margins, you can use `place` in @page.foreground or @page.background.
///
/// = Examples <examples>
/// ```example
/// #set page(height: 120pt)
/// Hello, world!
///
/// #rect(
///   width: 100%,
///   height: 2cm,
///   place(horizon + right, square()),
/// )
///
/// #place(
///   top + left,
///   dx: -5pt,
///   square(size: 5pt, fill: red),
/// )
/// ```
///
/// = #short-or-long[Effect On Other Elements][
///   Effect on the position of other elements
/// ] <effect-on-other-elements>
/// Overlaid elements don't take space in the flow of content, but a `place`
/// call inserts an invisible block-level element in the flow. This can affect
/// the layout by breaking the current paragraph. To avoid this, you can wrap
/// the `place` call in a @box when the call is made in the middle of a
/// paragraph. The alignment and offsets will then be relative to this zero-size
/// box. To make sure it doesn't interfere with spacing, the box should be
/// attached to a word using a word joiner.
///
/// For example, the following defines a function for attaching an annotation to
/// the following word:
///
/// ```example
/// >>> #set page(height: 70pt)
/// #let annotate(..args) = {
///   box(place(..args))
///   sym.wj
///   h(0pt, weak: true)
/// }
///
/// A placed #annotate(square(), dy: 2pt)
/// square in my text.
/// ```
///
/// The zero-width weak spacing serves to discard spaces between the function
/// call and the next word.
///
/// = Accessibility <accessibility>
/// Assistive Technology (AT) will always read the placed element at the point
/// where it logically appears in the document, regardless of where this
/// function physically moved it. Put its markup where it would make the most
/// sense in the reading order.
#[elem(scope, since = "forever", Unqueriable, Locatable, Tagged)]
pub struct PlaceElem {
    /// Relative to which position in the parent container to place the content.
    ///
    /// - If `float` is `{false}`, then this can be any alignment other than
    ///   `{auto}`.
    /// - If `float` is `{true}`, then this must be `{auto}`, `{top}`, or
    ///   `{bottom}`.
    ///
    /// When `float` is `{false}` and no vertical alignment is specified, the
    /// content is placed at the current position on the vertical axis.
    #[positional]
    #[default(Smart::Custom(Alignment::START))]
    pub alignment: Smart<Alignment>,

    /// Relative to which containing scope something is placed.
    ///
    /// The parent scope is primarily used with figures and, for this reason,
    /// the figure function has a mirrored @figure.scope[`scope` parameter].
    /// Nonetheless, it can also be more generally useful to break out of the
    /// columns. A typical example would be to
    /// @guides:page-setup:columns[create a single-column title section] in a
    /// two-column document.
    ///
    /// Note that parent-scoped placement is currently only supported if `float`
    /// is `{true}`. This may change in the future.
    ///
    /// ```example
    /// #set page(height: 150pt, columns: 2)
    /// #place(
    ///   top + center,
    ///   scope: "parent",
    ///   float: true,
    ///   rect(width: 80%, fill: aqua),
    /// )
    ///
    /// #lorem(25)
    /// ```
    pub scope: PlacementScope,

    /// Whether the placed element has floating layout.
    ///
    /// Floating elements are positioned at the top or bottom of the parent
    /// container, displacing in-flow content. They are always placed in the
    /// in-flow order relative to each other, as well as before any content
    /// following a later @place.flush element.
    ///
    /// ```example
    /// #set page(height: 150pt)
    /// #let note(where, body) = place(
    ///   center + where,
    ///   float: true,
    ///   clearance: 6pt,
    ///   rect(body),
    /// )
    ///
    /// #lorem(10)
    /// #note(bottom)[Bottom 1]
    /// #note(bottom)[Bottom 2]
    /// #lorem(40)
    /// #note(top)[Top]
    /// #lorem(10)
    /// ```
    pub float: bool,

    /// The spacing between the placed element and other elements in a floating
    /// layout.
    ///
    /// Has no effect if `float` is `{false}`.
    #[default(Em::new(1.5).into())]
    pub clearance: Length,

    /// The horizontal displacement of the placed content.
    ///
    /// ```example
    /// #set page(height: 100pt)
    /// #for x in range(-8, 8) {
    ///   place(center + horizon,
    ///     dx: x * 8pt, dy: x * 4pt,
    ///     text(
    ///       size: calc.root(x + 10, 3) * 6pt,
    ///       fill: color.mix((green, 8 - x), (blue, 8 + x)),
    ///     )[T]
    ///   )
    /// }
    /// ```
    ///
    /// This does not affect the layout of in-flow content. In other words, the
    /// placed content is treated as if it were wrapped in a @move element.
    pub dx: Rel<Length>,

    /// The vertical displacement of the placed content.
    ///
    /// This does not affect the layout of in-flow content. In other words, the
    /// placed content is treated as if it were wrapped in a @move element.
    pub dy: Rel<Length>,

    /// The content to place.
    #[required]
    pub body: Content,
}

#[scope]
impl PlaceElem {
    #[elem]
    type FlushElem;
}

/// Relative to which containing scope something shall be placed.
#[derive(Debug, Default, Copy, Clone, Eq, PartialEq, Hash, Cast)]
pub enum PlacementScope {
    /// Place into the current column.
    #[default]
    Column,
    /// Place relative to the parent, letting the content span over all columns.
    Parent,
}

/// Asks the layout algorithm to place pending floating elements before
/// continuing with the content.
///
/// This is useful for preventing floating figures from spilling into the next
/// section.
///
/// ```example
/// >>> #set page(height: 160pt, width: 150pt)
/// #lorem(15)
///
/// #figure(
///   rect(width: 100%, height: 50pt),
///   placement: auto,
///   caption: [A rectangle],
/// )
///
/// #place.flush()
///
/// This text appears after the figure.
/// ```
#[elem(since = "0.12.0")]
pub struct FlushElem {}

use std::num::NonZeroUsize;
use std::ops::RangeInclusive;
use std::str::FromStr;

use typst_utils::{NonZeroExt, Scalar, singleton};

use crate::diag::{HintedStrResult, SourceResult, bail};
use crate::engine::Engine;
use crate::foundations::{
    Args, Cast, CastInfo, Construct, Content, Dict, Fold, FromValue, IntoValue,
    NativeElement, Reflect, Set, Smart, Value, cast, elem,
};
use crate::layout::{
    Abs, Alignment, FlushElem, HAlignment, Length, OuterVAlignment, Ratio, Rel, Sides,
    SpecificAlignment,
};
use crate::model::Numbering;
use crate::text::LocalName;
use crate::visualize::Paint;

/// Layouts its child onto one or multiple pages.
///
/// Although this function is primarily used in set rules to affect page
/// properties, it can also be used to explicitly render its argument onto a set
/// of pages of its own.
///
/// Pages can be set to use `{auto}` as their width or height. In this case, the
/// pages will grow to fit their content on the respective axis.
///
/// The @guides:page-setup[Guide for Page Setup] explains how to use this and
/// related functions to set up a document with many examples.
///
/// = Example <example>
/// ```example
/// >>> #set page(margin: auto)
/// #set page("us-letter")
///
/// There you go, US friends!
/// ```
///
/// = Accessibility <accessibility>
/// The contents of the page's header, footer, foreground, and background are
/// invisible to Assistive Technology (AT) like screen readers. Only the body of
/// the page is read by AT. Do not include vital information not included
/// elsewhere in the document in these areas.
///
/// = Styling <styling>
/// Note that the @page element cannot be targeted by show rules; writing
/// `{show page: ..}` has no effect. To repeat content on every page, you can
/// instead configure the @page.header[`header`], @page.footer[`footer`],
/// @page.background[`background`], and @page.foreground[`foreground`]
/// properties with a set rule.
#[elem(since = "forever", Construct)]
pub struct PageElem {
    /// A standard paper size to set width and height.
    ///
    /// This is just a shorthand for setting `width` and `height` and, as such,
    /// cannot be retrieved in a context expression.
    #[external]
    #[default(Paper::A4)]
    pub paper: Paper,

    /// The width of the final page, after any trims have been applied.
    ///
    /// In professional printing setups, this may be smaller than the sheet size
    /// fed into the printer.
    ///
    /// See the @page.bleed[`bleed`] parameter for details on how to set a trim
    /// or bleed area.
    ///
    /// ```example
    /// #set page(
    ///   width: 3cm,
    ///   margin: (x: 0cm),
    /// )
    ///
    /// #for i in range(3) {
    ///   box(square(width: 1cm))
    /// }
    /// ```
    #[parse(
        let paper = args.named_or_find::<Paper>("paper")?;
        args.named("width")?
            .or_else(|| paper.map(|paper| Smart::Custom(paper.width().into())))
    )]
    #[default(Smart::Custom(Paper::A4.width().into()))]
    #[ghost]
    pub width: Smart<Length>,

    /// The height of the final page area, after any trims have been applied.
    ///
    /// If this is set to `{auto}`, page breaks can only be triggered manually
    /// by inserting a @pagebreak[page break] or by adding another non-empty
    /// page set rule. Most examples throughout this documentation use `{auto}`
    /// for the height of the page to dynamically grow and shrink to fit their
    /// content.
    #[parse(
        args.named("height")?
            .or_else(|| paper.map(|paper| Smart::Custom(paper.height().into())))
    )]
    #[default(Smart::Custom(Paper::A4.height().into()))]
    #[ghost]
    pub height: Smart<Length>,

    /// Whether the page is flipped into landscape orientation.
    ///
    /// ```example
    /// #set page(
    ///   "us-business-card",
    ///   flipped: true,
    ///   fill: rgb("f2e5dd"),
    /// )
    ///
    /// #set align(bottom + end)
    /// #text(14pt)[*Sam H. Richards*] \
    /// _Procurement Manager_
    ///
    /// #set text(10pt)
    /// 23 W 23rd Street \
    /// New York, NY 10010 \
    /// +1 (212) 555-0155
    /// ```
    #[default(false)]
    #[ghost]
    pub flipped: bool,

    /// The page's margins.
    ///
    /// - `{auto}`: The margins are set automatically to 2.5/21 times the
    ///   smaller dimension of the page. This results in 2.5 cm margins for an
    ///   A4 page.
    /// - A single length: The same margin on all sides.
    /// - A dictionary: With a dictionary, the margins can be set individually.
    ///   The dictionary can contain the following keys in order of precedence:
    ///   - `top`: The top margin.
    ///   - `right`: The right margin.
    ///   - `bottom`: The bottom margin.
    ///   - `left`: The left margin.
    ///   - `inside`: The margin at the inner side of the page (where the
    ///     @page.binding[binding] is).
    ///   - `outside`: The margin at the outer side of the page (opposite to the
    ///     @page.binding[binding]).
    ///   - `x`: The horizontal margins.
    ///   - `y`: The vertical margins.
    ///   - `rest`: The margins on all sides except those for which the
    ///     dictionary explicitly sets a size.
    ///
    /// All keys are optional; omitted keys will use their previously set value,
    /// or the default margin if never set. In addition, the values for `left`
    /// and `right` are mutually exclusive with the values for `inside` and
    /// `outside`. The values should be relative lengths or `{auto}`.
    ///
    /// ```example
    /// #set page(
    ///  width: 3cm,
    ///  height: 4cm,
    ///  margin: (x: 8pt, y: 4pt),
    /// )
    ///
    /// #rect(
    ///   width: 100%,
    ///   height: 100%,
    ///   fill: aqua,
    /// )
    /// ```
    #[fold]
    #[ghost]
    pub margin: Smart<Margin<Smart<Rel<Length>>>>,

    /// The page's bleed margin.
    ///
    /// The bleed is the area of content that extends beyond the final trimmed
    /// size of the page. It ensures that no unprinted edges appear in the final
    /// product, even if minor trimming misalignments occur.
    ///
    /// Accepted values:
    ///
    /// - A single length: The same bleed on all sides.
    /// - A dictionary: With a dictionary, the bleed margins can be set
    ///   individually. The dictionary may include the following keys, listed in
    ///   order of precedence:
    ///   - `top`: The top bleed margin.
    ///   - `right`: The right bleed margin.
    ///   - `bottom`: The bottom bleed margin.
    ///   - `left`: The left bleed margin.
    ///   - `inside`: The bleed margin at the inner side of the page (where the
    ///     @page.binding[binding] is).
    ///   - `outside`: The bleed margin at the outer side of the page (opposite
    ///     to the @page.binding[binding]).
    ///   - `x`: The horizontal bleed margins.
    ///   - `y`: The vertical bleed margins.
    ///   - `rest`: The bleed margins on all sides except those for which the
    ///     dictionary explicitly sets a size.
    ///
    /// All keys are optional; omitted keys will use their previously set value,
    /// or `{0pt}` if never set. In addition, the values for `left` and `right`
    /// are mutually exclusive with the values for `inside` and `outside`. The
    /// values should be relative lengths.
    ///
    /// In PDF export, if the bleed is non-zero, a `TrimBox` is defined for the
    /// page.
    ///
    /// ```example
    /// #set page(
    ///   width: 8cm,
    ///   height: 5cm,
    ///   margin: 1cm,
    ///   // The bleed is not visible in the preview;
    ///   // it exceeds beyond the page.
    ///   bleed: 0.5cm,
    ///   // Fills the entire bleed area, so there will
    ///   // be no white strips after printing and trimming.
    ///   background: rect(width: 100%, height: 100%, fill: aqua),
    /// )
    ///
    /// #rect(width: 100%, height: 100%, fill: white)
    /// ```
    #[ghost]
    pub bleed: Margin<Rel<Length>>,

    /// On which side the pages will be bound.
    ///
    /// - `{auto}`: Equivalent to `left` if the @text.dir[text direction] is
    ///   left-to-right and `right` if it is right-to-left.
    /// - `left`: Bound on the left side.
    /// - `right`: Bound on the right side.
    ///
    /// This affects the meaning of the `inside` and `outside` options for
    /// margins.
    #[ghost]
    pub binding: Smart<Binding>,

    /// How many columns the page has.
    ///
    /// If you need to insert columns into a page or other container, you can
    /// also use the @columns[`columns` function].
    ///
    /// #example(
    ///   single: true,
    ///   ```
    ///   #set page(columns: 2, height: 4.8cm)
    ///   Climate change is one of the most
    ///   pressing issues of our time, with
    ///   the potential to devastate
    ///   communities, ecosystems, and
    ///   economies around the world. It's
    ///   clear that we need to take urgent
    ///   action to reduce our carbon
    ///   emissions and mitigate the impacts
    ///   of a rapidly changing climate.
    ///   ```
    /// )
    #[default(NonZeroUsize::ONE)]
    #[ghost]
    pub columns: NonZeroUsize,

    /// The page's background fill.
    ///
    /// Setting this to something non-transparent instructs the printer to color
    /// the complete page. If you are considering larger production runs, it may
    /// be more environmentally friendly and cost-effective to source pre-dyed
    /// pages and not set this property.
    ///
    /// When set to `{none}`, the background becomes transparent. Note that PDF
    /// pages will still appear with a (usually white) background in viewers,
    /// but they are actually transparent. (If you print them, no color is used
    /// for the background.)
    ///
    /// The default of `{auto}` results in `{none}` for PDF output, and
    /// `{white}` for PNG and SVG.
    ///
    /// ```example
    /// #set page(fill: rgb("444352"))
    /// #set text(fill: rgb("fdfdfd"))
    /// *Dark mode enabled.*
    /// ```
    #[ghost]
    pub fill: Smart<Option<Paint>>,

    /// How to number the pages. You can refer to the Page Setup Guide for
    /// @guides:page-setup:page-numbers[customizing page numbers].
    ///
    /// Accepts a @numbering[numbering pattern or function] taking one or two
    /// numbers:
    /// + The first number is the current page number.
    /// + The second number is the total number of pages. In a numbering
    ///   pattern, the second number can be omitted. If a function is passed, it
    ///   will receive one argument in the context of links or references, and
    ///   two arguments when producing the visible page numbers.
    ///
    /// These are logical numbers controlled by the page counter, and may thus
    /// not match the physical numbers. Specifically, they are the
    /// @counter.get[current] and the @counter.final[final] value of
    /// `{counter(page)}`. See the @counter:page-counter[`counter`]
    /// documentation for more details.
    ///
    /// If an explicit @page.footer[`footer`] (or @page.header[`header`] for
    /// @page.number-align[top-aligned] numbering) is given, the numbering is
    /// ignored.
    ///
    /// ```example
    /// #set page(
    ///   height: 100pt,
    ///   margin: (top: 16pt, bottom: 24pt),
    ///   numbering: "1 / 1",
    /// )
    ///
    /// #lorem(48)
    /// ```
    #[ghost]
    pub numbering: Option<Numbering>,

    /// A supplement for the pages.
    ///
    /// For page references, this is added before the page number.
    ///
    /// ```example
    /// #set page(numbering: "1.", supplement: [p.])
    ///
    /// = Introduction <intro>
    /// We are on #ref(<intro>, form: "page")!
    /// ```
    #[ghost]
    pub supplement: Smart<Option<Content>>,

    /// The alignment of the page numbering.
    ///
    /// If the vertical component is `top`, the numbering is placed into the
    /// header and if it is `bottom`, it is placed in the footer. Horizon
    /// alignment is forbidden. If an explicit matching `header` or `footer` is
    /// given, the numbering is ignored.
    ///
    /// ```example
    /// #set page(
    ///   margin: (top: 16pt, bottom: 24pt),
    ///   numbering: "1",
    ///   number-align: right,
    /// )
    ///
    /// #lorem(30)
    /// ```
    #[default(SpecificAlignment::Both(HAlignment::Center, OuterVAlignment::Bottom))]
    #[ghost]
    pub number_align: SpecificAlignment<HAlignment, OuterVAlignment>,

    /// The page's header. Fills the top margin of each page.
    ///
    /// - Content: Shows the content as the header.
    /// - `{auto}`: Shows the page number if a @page.numbering[`numbering`] is
    ///   set and @page.number-align[`number-align`] is `top`.
    /// - `{none}`: Suppresses the header.
    ///
    /// ```example
    /// #set par(justify: true)
    /// #set page(
    ///   margin: (top: 32pt, bottom: 20pt),
    ///   header: [
    ///     #set text(8pt)
    ///     #smallcaps[Typst Academy]
    ///     #h(1fr) _Exercise Sheet 3_
    ///   ],
    /// )
    ///
    /// #lorem(19)
    /// ```
    #[ghost]
    pub header: Smart<Option<Content>>,

    /// The amount the header is raised into the top margin. Ratios are relative
    /// to the height of the top margin.
    #[default(Ratio::new(0.3).into())]
    #[ghost]
    pub header_ascent: Rel<Length>,

    /// The page's footer. Fills the bottom margin of each page.
    ///
    /// - Content: Shows the content as the footer.
    /// - `{auto}`: Shows the page number if a @page.numbering[`numbering`] is
    ///   set and @page.number-align[`number-align`] is `bottom`.
    /// - `{none}`: Suppresses the footer.
    ///
    /// For just a page number, the `numbering` property typically suffices. If
    /// you want to create a custom footer but still display the page number,
    /// you can directly access the @counter[page counter].
    ///
    /// ```example
    /// #set par(justify: true)
    /// #set page(
    ///   height: 100pt,
    ///   margin: 20pt,
    ///   footer: context [
    ///     #set align(right)
    ///     #set text(8pt)
    ///     #counter(page).display(
    ///       "1 of I",
    ///       both: true,
    ///     )
    ///   ]
    /// )
    ///
    /// #lorem(48)
    /// ```
    #[ghost]
    pub footer: Smart<Option<Content>>,

    /// The amount the footer is lowered into the bottom margin. Ratios are
    /// relative to the height of the bottom margin.
    ///
    /// ```preview
    /// #set page(
    ///   height: 126pt,
    ///   width: 240pt,
    ///   margin: (top: 0pt, x: 20pt, bottom: 50pt),
    ///   numbering: (..nums) => box(
    ///     outset: (x: 50%),
    ///     fill: orange.lighten(50%),
    ///   )[6 / 8],
    ///   footer-descent: 47%,
    ///   foreground: place(bottom, {
    ///     let arrow(height) = math.stretch(
    ///       text(1.4em, sym.arrow.t.b),
    ///       size: height,
    ///     )
    ///     set text(
    ///       1.2em,
    ///       purple.darken(10%),
    ///       bottom-edge: "bounds",
    ///       top-edge: "bounds",
    ///     )
    ///     set par(leading: 0.5em)
    ///     import grid: cell
    ///     context grid(
    ///       align: center + horizon,
    ///       columns: (37%, 10%, 6%, 47%),
    ///       cell(rowspan: 2, align: right)[bottom\ margin],
    ///       cell(rowspan: 2, align: left, arrow(page.margin.bottom)),
    ///       arrow(page.margin.bottom * page.footer-descent.ratio),
    ///       cell(align: left)[footer descent],
    ///     )
    ///   }),
    /// )
    /// #block(width: 100%, height: 100%, fill: green.lighten(75%), {
    ///   set par(justify: true)
    ///   set text(luma(25%))
    ///   place(bottom, lorem(42))
    /// })
    /// ```
    #[default(Ratio::new(0.3).into())]
    #[ghost]
    pub footer_descent: Rel<Length>,

    /// Content in the page's background.
    ///
    /// This content will be placed behind the page's body. It can be used to
    /// place a background image or a watermark.
    ///
    /// For convenience, @relative[relative lengths] are resolved against the
    /// page size including the @page.bleed[page `bleed`] when used in
    /// background content. For example, on a page that is `{100mm}` wide with a
    /// `{5mm}` bleed, a width of `{100%}` is computed as `{5mm + 100mm + 5mm}`.
    ///
    /// ```example
    /// #set page(background: rotate(24deg,
    ///   text(18pt, fill: rgb("FFCBC4"))[
    ///     *CONFIDENTIAL*
    ///   ]
    /// ))
    ///
    /// = Typst's secret plans
    /// In the year 2023, we plan to take
    /// over the world (of typesetting).
    /// ```
    #[ghost]
    pub background: Option<Content>,

    /// Content in the page's foreground.
    ///
    /// This content will overlay the page's body.
    ///
    /// Relative lengths are resolved against the page size including
    /// @page.bleed[`bleed`], following the same behavior as
    /// @page.background[`background`].
    ///
    /// ```example
    /// #set page(foreground: text(24pt)[🤓])
    ///
    /// Reviewer 2 has marked our paper
    /// "Weak Reject" because they did
    /// not understand our approach...
    /// ```
    #[ghost]
    pub foreground: Option<Content>,

    /// The contents of the page(s).
    ///
    /// Multiple pages will be created if the content does not fit on a single
    /// page. A new page with the page properties prior to the function
    /// invocation will be created after the body has been typeset.
    #[external]
    #[required]
    pub body: Content,
}

impl Construct for PageElem {
    fn construct(engine: &mut Engine, args: &mut Args) -> SourceResult<Content> {
        // The page constructor is special: It doesn't create a page element.
        // Instead, it just ensures that the passed content lives in a separate
        // page and styles it. Because no element node is produced, `show`
        // rules can't match `page`; use `set` rules instead.
        let styles = Self::set(engine, args)?;
        let body = args.expect::<Content>("body")?;
        Ok(Content::sequence([
            PagebreakElem::shared_weak().clone(),
            // We put an effectless, invisible non-tag element on the page.
            // This has two desirable consequences:
            // - The page is kept even if the body is empty
            // - The page doesn't inherit shared styles from the body
            FlushElem::new().pack(),
            body,
            PagebreakElem::shared_boundary().clone(),
        ])
        .styled_with_map(styles))
    }
}

impl LocalName for PageElem {
    const KEY: &'static str = "page";
}

/// A manual page break.
///
/// Must not be used inside any containers.
///
/// = Example <example>
/// ```example
/// The next page contains
/// more details on compound theory.
/// #pagebreak()
///
/// == Compound Theory
/// In 1984, the first ...
/// ```
///
/// Even without manual page breaks, content will be automatically paginated
/// based on the configured page size. You can set @page.height[the page height]
/// to `{auto}` to let the page grow dynamically until a manual page break
/// occurs.
///
/// Pagination tries to avoid single lines of text at the top or bottom of a
/// page (these are called _widows_ and _orphans_). You can adjust the
/// @text.costs parameter to disable this behavior.
#[elem(title = "Page Break", since = "forever")]
pub struct PagebreakElem {
    /// If `{true}`, the page break is skipped if the current page is already
    /// empty.
    #[default(false)]
    pub weak: bool,

    /// If given, ensures that the next page will be an even/odd page, with an
    /// empty page in between if necessary.
    ///
    /// ```example
    /// #set page(height: 30pt)
    ///
    /// First.
    /// #pagebreak(to: "odd")
    /// Third.
    /// ```
    pub to: Option<Parity>,

    /// Whether this pagebreak designates an end boundary of a page run. This is
    /// an even weaker version of pagebreak `weak` because it not only doesn't
    /// force an empty page, but also doesn't force its initial styles onto a
    /// staged empty page.
    #[internal]
    #[parse(None)]
    #[default(false)]
    pub boundary: bool,
}

impl PagebreakElem {
    /// Get the globally shared weak pagebreak element.
    pub fn shared_weak() -> &'static Content {
        singleton!(Content, PagebreakElem::new().with_weak(true).pack())
    }

    /// Get the globally shared boundary pagebreak element.
    pub fn shared_boundary() -> &'static Content {
        singleton!(
            Content,
            PagebreakElem::new().with_weak(true).with_boundary(true).pack()
        )
    }
}

/// Specification of the page's margins.
#[derive(Debug, Default, Copy, Clone, Eq, PartialEq, Hash)]
pub struct Margin<T: PartialEq> {
    /// The margins for each side.
    pub sides: Sides<Option<T>>,
    /// Whether to swap `left` and `right` to make them `inside` and `outside`
    /// (when to swap depends on the binding).
    pub two_sided: Option<bool>,
}

impl<T: Clone + PartialEq> Margin<T> {
    /// Create an instance with four equal components.
    pub fn splat(value: Option<T>) -> Self {
        Self { sides: Sides::splat(value), two_sided: None }
    }
}

impl<T: Fold + PartialEq> Fold for Margin<T> {
    fn fold(self, outer: Self) -> Self {
        Margin {
            sides: self.sides.fold(outer.sides),
            two_sided: self.two_sided.fold(outer.two_sided),
        }
    }
}

impl<T: Reflect + PartialEq> Reflect for Margin<T> {
    fn input() -> CastInfo {
        T::input() + Dict::input()
    }

    fn output() -> CastInfo {
        Self::input()
    }

    fn castable(value: &Value) -> bool {
        T::castable(value) || Dict::castable(value)
    }
}

impl<T: IntoValue + PartialEq> IntoValue for Margin<T> {
    fn into_value(self) -> Value {
        let two_sided = self.two_sided.unwrap_or(false);
        if !two_sided
            && self.sides.is_uniform()
            && let Some(left) = self.sides.left
        {
            return left.into_value();
        }

        let mut dict = Dict::new();
        let mut handle = |key: &str, component: Option<T>| {
            if let Some(c) = component {
                dict.insert(key.into(), c.into_value());
            }
        };

        handle("top", self.sides.top);
        handle("bottom", self.sides.bottom);
        if two_sided {
            handle("inside", self.sides.left);
            handle("outside", self.sides.right);
        } else {
            handle("left", self.sides.left);
            handle("right", self.sides.right);
        }

        Value::Dict(dict)
    }
}

impl<T: Reflect + FromValue + Copy + PartialEq> FromValue for Margin<T> {
    fn from_value(value: Value) -> HintedStrResult<Self> {
        if T::castable(&value) {
            let v = T::from_value(value)?;
            return Ok(Self::splat(Some(v)));
        }

        if Dict::castable(&value) {
            let mut dict = Dict::from_value(value)?;
            let mut take = |key| dict.take(key).ok().map(Value::cast).transpose();

            let rest = take("rest")?;
            let x = take("x")?.or(rest);
            let y = take("y")?.or(rest);
            let top = take("top")?.or(y);
            let bottom = take("bottom")?.or(y);
            let outside = take("outside")?;
            let inside = take("inside")?;
            let left = take("left")?;
            let right = take("right")?;

            let implicitly_two_sided = outside.is_some() || inside.is_some();
            let implicitly_not_two_sided = left.is_some() || right.is_some();
            if implicitly_two_sided && implicitly_not_two_sided {
                bail!(
                    "`inside` and `outside` are mutually exclusive with `left` and `right`"
                );
            }

            // - If 'implicitly_two_sided' is false here, then
            //   'implicitly_not_two_sided' will be guaranteed to be true
            //    due to the previous two 'if' conditions.
            // - If both are false, this means that this margin change does not
            //   affect lateral margins, and thus shouldn't make a difference on
            //   the 'two_sided' attribute of this margin.
            let two_sided = (implicitly_two_sided || implicitly_not_two_sided)
                .then_some(implicitly_two_sided);

            dict.finish(&[
                "left", "top", "right", "bottom", "outside", "inside", "x", "y", "rest",
            ])?;

            return Ok(Margin {
                sides: Sides {
                    left: inside.or(left).or(x),
                    top,
                    right: outside.or(right).or(x),
                    bottom,
                },
                two_sided,
            });
        }

        Err(Self::error(&value))
    }
}

/// Specification of the page's binding.
#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash)]
pub enum Binding {
    /// Bound on the left, as customary in LTR languages.
    Left,
    /// Bound on the right, as customary in RTL languages.
    Right,
}

impl Binding {
    /// Whether to swap left and right margin for the page with this number.
    pub fn swap(self, number: NonZeroUsize) -> bool {
        match self {
            // Left-bound must swap on even pages
            // (because it is correct on the first page).
            Self::Left => number.get() % 2 == 0,
            // Right-bound must swap on odd pages
            // (because it is wrong on the first page).
            Self::Right => number.get() % 2 == 1,
        }
    }
}

cast! {
    Binding,
    self => match self {
        Self::Left => Alignment::LEFT.into_value(),
        Self::Right => Alignment::RIGHT.into_value(),
    },
    v: Alignment => match v {
        Alignment::LEFT => Self::Left,
        Alignment::RIGHT => Self::Right,
        _ => bail!("must be `left` or `right`"),
    },
}

/// A list of page ranges to be exported.
#[derive(Debug, Clone, Hash)]
pub struct PageRanges(Vec<PageRange>);

/// A range of pages to export.
///
/// The range is one-indexed. For example, `1..=3` indicates the first, second
/// and third pages should be exported.
pub type PageRange = RangeInclusive<Option<NonZeroUsize>>;

impl PageRanges {
    /// Create new page ranges.
    pub fn new(ranges: Vec<PageRange>) -> Self {
        Self(ranges)
    }

    /// Check if a page, given its number, should be included when exporting the
    /// document while restricting the exported pages to these page ranges.
    /// This is the one-indexed version of [`Self::includes_page_index`].
    pub fn includes_page(&self, page: NonZeroUsize) -> bool {
        self.includes_page_index(page.get() - 1)
    }

    /// Check if a page, given its index, should be included when exporting the
    /// document while restricting the exported pages to these page ranges.
    /// This is the zero-indexed version of [`Self::includes_page`].
    pub fn includes_page_index(&self, page: usize) -> bool {
        let page = NonZeroUsize::try_from(page + 1).unwrap();
        self.0.iter().any(|range| match (range.start(), range.end()) {
            (Some(start), Some(end)) => (start..=end).contains(&&page),
            (Some(start), None) => (start..).contains(&&page),
            (None, Some(end)) => (..=end).contains(&&page),
            (None, None) => true,
        })
    }
}

/// Whether something should be even or odd.
#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash, Cast)]
pub enum Parity {
    /// Next page will be an even page.
    Even,
    /// Next page will be an odd page.
    Odd,
}

impl Parity {
    /// Whether the given number matches the parity.
    pub fn matches(self, number: usize) -> bool {
        match self {
            Self::Even => number % 2 == 0,
            Self::Odd => number % 2 == 1,
        }
    }
}

/// Specification of a paper.
#[derive(Debug, Copy, Clone, Hash)]
pub struct Paper {
    /// The name of the paper.
    name: &'static str,
    /// The width of the paper in millimeters.
    width: Scalar,
    /// The height of the paper in millimeters.
    height: Scalar,
}

impl Paper {
    /// The width of the paper.
    pub fn width(self) -> Abs {
        Abs::mm(self.width.get())
    }

    /// The height of the paper.
    pub fn height(self) -> Abs {
        Abs::mm(self.height.get())
    }
}

/// Defines paper constants and a paper parsing implementation.
macro_rules! papers {
    ($(($var:ident: $width:expr, $height: expr, $name:literal))*) => {
        /// Predefined papers.
        ///
        /// Each paper is parsable from its name in kebab-case.
        impl Paper {
            $(pub const $var: Self = Self {
                name: $name,
                width: Scalar::new($width),
                height: Scalar::new($height),
            };)*
        }

        impl FromStr for Paper {
            type Err = &'static str;

            fn from_str(name: &str) -> Result<Self, Self::Err> {
                match name.to_lowercase().as_str() {
                    $($name => Ok(Self::$var),)*
                    _ => Err("unknown paper size"),
                }
            }
        }

        cast! {
            Paper,
            self => self.name.into_value(),
            $(
                /// A paper that is
                #[doc = stringify!($width)]
                /// ×
                #[doc = stringify!($height)]
                /// millimeters in size.
                $name => Self::$var,
            )*
        }
    };
}

